import unittest
from TTT import choose_first
from os import system
import random

class Test_TttChooseFirst(unittest.TestCase):

    @unittest.skip("smoke")
    def test_random_selection_between_players(self):
        player1_count = 0
        player2_count = 0
        iterations = 10000  # Large number to ensure statistical significance

        for _ in range(iterations):
            result = choose_first()
            if result == 'Player 1':
                player1_count += 1
            elif result == 'Player 2':
                player2_count += 1

        # Assert that both players are chosen approximately 50% of the time
